/**
 * tokens.css — Sando UI design tokens: the brand-invariant base (Cmp tier + type roles).
 *
 * DO NOT EDIT DIRECTLY. Generated from the DTCG source under tokens/ via Style Dictionary.
 * Edit the JSON source and run `npm run token:build`.
 *
 * Ref + Sys live in a BRAND file beside this one (src/styles/themes/<brand>.css) — one per theme,
 * because a theme changes token NAMES as well as values (a Ref rung is named by its value). Load
 * this file plus at least one brand file; import order between them does not matter.
 */

:root {
  /* ═══ Cmp — component tokens (reference Sys) ═══ */
  /* color-swatch */
  --sd-color-swatch-size-small: var(--sd-size-x-small);
  --sd-color-swatch-size-medium: var(--sd-size-small);
  --sd-color-swatch-size-large: var(--sd-size-medium);
  --sd-color-swatch-radius: var(--sd-radius-medium);
  --sd-color-swatch-border: var(--sd-color-border-decorative);
  --sd-color-swatch-border-width: var(--sd-border-thin);

  /* color-swatch-picker */
  --sd-color-swatch-picker-gap: var(--sd-space-x-small);
  --sd-color-swatch-picker-item-padding: var(--sd-space-x-small);
  --sd-color-swatch-picker-item-background: var(--sd-color-surface-inset);
  --sd-color-swatch-picker-item-border: var(--sd-color-border);
  --sd-color-swatch-picker-item-border-hover: var(--sd-color-border-hover);
  --sd-color-swatch-picker-item-border-selected: var(--sd-color-border-accent);
  --sd-color-swatch-picker-item-radius: var(--sd-radius-control-medium);
  --sd-color-swatch-picker-item-shadow-selected: 0 0 0 2px color-mix(in srgb, var(--sd-color-border-accent) 32%, transparent);
  --sd-color-swatch-picker-item-border-width: var(--sd-border-thin);
  --sd-color-swatch-picker-swatch-radius: var(--sd-radius-small);

  /* color-field */
  --sd-color-field-text-padding-inline: var(--sd-text-inset-inline);
  --sd-color-field-gap: var(--sd-space-x-small);
  --sd-color-field-label-foreground: var(--sd-color-text);
  --sd-color-field-label-group-gap: var(--sd-space-2x-small);
  --sd-color-field-input-background: var(--sd-color-surface-inset);
  --sd-color-field-input-background-readonly: var(--sd-color-surface);
  --sd-color-field-input-foreground: var(--sd-color-text);
  --sd-color-field-input-placeholder: var(--sd-color-text-placeholder);
  --sd-color-field-input-border: var(--sd-color-border);
  --sd-color-field-input-border-hover: var(--sd-color-border-hover);
  --sd-color-field-input-border-focus: var(--sd-color-border-focus);
  --sd-color-field-input-border-invalid: var(--sd-color-border-invalid);
  --sd-color-field-input-radius-x-small: var(--sd-radius-control-x-small);
  --sd-color-field-input-radius-small: var(--sd-radius-control-small);
  --sd-color-field-input-radius-medium: var(--sd-radius-control-medium);
  --sd-color-field-input-radius-large: var(--sd-radius-control-large);
  --sd-color-field-input-radius-x-large: var(--sd-radius-control-x-large);
  --sd-color-field-input-height-x-small: var(--sd-control-height-x-small);
  --sd-color-field-input-height-small: var(--sd-control-height-small);
  --sd-color-field-input-height-medium: var(--sd-control-height-medium);
  --sd-color-field-input-height-large: var(--sd-control-height-large);
  --sd-color-field-input-height-x-large: var(--sd-control-height-x-large);
  --sd-color-field-input-padding-inline-x-small: var(--sd-space-small);
  --sd-color-field-input-padding-inline-small: var(--sd-space-small);
  --sd-color-field-input-padding-inline-medium: var(--sd-space-medium);
  --sd-color-field-input-padding-inline-large: var(--sd-space-large);
  --sd-color-field-input-padding-inline-x-large: var(--sd-space-large);
  --sd-color-field-input-border-width: var(--sd-border-thin);
  --sd-color-field-description-foreground: var(--sd-color-text-muted);
  --sd-color-field-error-foreground: var(--sd-color-text-error);

  /* color-area */
  --sd-color-area-size: 12rem;
  --sd-color-area-radius: var(--sd-radius-medium);
  --sd-color-area-thumb-size: 1rem;
  --sd-color-area-thumb-size-focused: 1.25rem;
  --sd-color-area-thumb-border-width: var(--sd-border-medium);
  --sd-color-area-thumb-border: var(--sd-color-border-on-color);
  --sd-color-area-thumb-radius: var(--sd-radius-full);
  --sd-color-area-thumb-shadow: 0 0 0 1px rgba(0, 0, 0, 0.85), inset 0 0 0 1px rgba(0, 0, 0, 0.85);
  --sd-color-area-thumb-shadow-hover: 0 0 0 1px rgba(0, 0, 0, 0.85), inset 0 0 0 1px rgba(0, 0, 0, 0.85), 0 0 0 6px color-mix(in srgb, var(--sd-color-border-accent) 12%, transparent);
  --sd-color-area-thumb-shadow-dragging: 0 0 0 1px rgba(0, 0, 0, 0.85), inset 0 0 0 1px rgba(0, 0, 0, 0.85), 0 0 0 6px color-mix(in srgb, var(--sd-color-border-accent) 24%, transparent);

  /* color-slider */
  --sd-color-slider-text-padding-inline: var(--sd-text-inset-inline);
  --sd-color-slider-gap: var(--sd-space-small);
  --sd-color-slider-label-foreground: var(--sd-color-text);
  --sd-color-slider-description-foreground: var(--sd-color-text-muted);
  --sd-color-slider-track-width-horizontal: 12rem;
  --sd-color-slider-track-width-vertical: 1rem;
  --sd-color-slider-track-height-horizontal: 1rem;
  --sd-color-slider-track-height-vertical: 12rem;
  --sd-color-slider-track-radius: var(--sd-radius-full);
  --sd-color-slider-thumb-size: 1rem;
  --sd-color-slider-thumb-size-focused: 1.25rem;
  --sd-color-slider-thumb-border-width: var(--sd-border-medium);
  --sd-color-slider-thumb-border: var(--sd-color-border-on-color);
  --sd-color-slider-thumb-radius: var(--sd-radius-full);
  --sd-color-slider-thumb-shadow: 0 0 0 1px rgba(0, 0, 0, 0.85), inset 0 0 0 1px rgba(0, 0, 0, 0.85);
  --sd-color-slider-thumb-shadow-hover: 0 0 0 1px rgba(0, 0, 0, 0.85), inset 0 0 0 1px rgba(0, 0, 0, 0.85), 0 0 0 6px color-mix(in srgb, var(--sd-color-border-accent) 12%, transparent);
  --sd-color-slider-thumb-shadow-dragging: 0 0 0 1px rgba(0, 0, 0, 0.85), inset 0 0 0 1px rgba(0, 0, 0, 0.85), 0 0 0 6px color-mix(in srgb, var(--sd-color-border-accent) 24%, transparent);

  /* color-wheel */
  --sd-color-wheel-text-padding-inline: var(--sd-text-inset-inline);
  --sd-color-wheel-description-foreground: var(--sd-color-text-muted);
  --sd-color-wheel-track-radius: var(--sd-radius-full);
  --sd-color-wheel-thumb-size: 1rem;
  --sd-color-wheel-thumb-size-focused: 1.25rem;
  --sd-color-wheel-thumb-border-width: var(--sd-border-medium);
  --sd-color-wheel-thumb-border: var(--sd-color-border-on-color);
  --sd-color-wheel-thumb-radius: var(--sd-radius-full);
  --sd-color-wheel-thumb-shadow: 0 0 0 1px rgba(0, 0, 0, 0.85), inset 0 0 0 1px rgba(0, 0, 0, 0.85);
  --sd-color-wheel-thumb-shadow-hover: 0 0 0 1px rgba(0, 0, 0, 0.85), inset 0 0 0 1px rgba(0, 0, 0, 0.85), 0 0 0 6px color-mix(in srgb, var(--sd-color-border-accent) 12%, transparent);
  --sd-color-wheel-thumb-shadow-dragging: 0 0 0 1px rgba(0, 0, 0, 0.85), inset 0 0 0 1px rgba(0, 0, 0, 0.85), 0 0 0 6px color-mix(in srgb, var(--sd-color-border-accent) 24%, transparent);

  /* color-picker */
  --sd-color-picker-trigger-gap: var(--sd-space-small);
  --sd-color-picker-trigger-height-x-small: var(--sd-control-height-x-small);
  --sd-color-picker-trigger-height-small: var(--sd-control-height-small);
  --sd-color-picker-trigger-height-medium: var(--sd-control-height-medium);
  --sd-color-picker-trigger-height-large: var(--sd-control-height-large);
  --sd-color-picker-trigger-height-x-large: var(--sd-control-height-x-large);
  --sd-color-picker-trigger-padding-inline-x-small: var(--sd-space-small);
  --sd-color-picker-trigger-padding-inline-small: var(--sd-space-small);
  --sd-color-picker-trigger-padding-inline-medium: var(--sd-space-medium);
  --sd-color-picker-trigger-padding-inline-large: var(--sd-space-large);
  --sd-color-picker-trigger-padding-inline-x-large: var(--sd-space-large);
  --sd-color-picker-trigger-background: var(--sd-color-surface-inset);
  --sd-color-picker-trigger-foreground: var(--sd-color-text);
  --sd-color-picker-trigger-border: var(--sd-color-border);
  --sd-color-picker-trigger-border-hover: var(--sd-color-border-hover);
  --sd-color-picker-trigger-border-focus: var(--sd-color-border-focus);
  --sd-color-picker-trigger-radius-x-small: var(--sd-radius-control-x-small);
  --sd-color-picker-trigger-radius-small: var(--sd-radius-control-small);
  --sd-color-picker-trigger-radius-medium: var(--sd-radius-control-medium);
  --sd-color-picker-trigger-radius-large: var(--sd-radius-control-large);
  --sd-color-picker-trigger-radius-x-large: var(--sd-radius-control-x-large);
  --sd-color-picker-trigger-border-width: var(--sd-border-thin);
  --sd-color-picker-swatch-size-x-small: 0.75rem;
  --sd-color-picker-swatch-size-small: 1rem;
  --sd-color-picker-swatch-size-medium: 1.25rem;
  --sd-color-picker-swatch-size-large: 1.5rem;
  --sd-color-picker-swatch-size-x-large: 1.75rem;
  --sd-color-picker-swatch-radius: var(--sd-radius-small);
  --sd-color-picker-dialog-gap: var(--sd-space-medium);

  /* button */
  --sd-button-gap: var(--sd-space-2x-small);
  --sd-button-backdrop-blur: var(--sd-blur-backdrop);
  --sd-button-plate-media-size: var(--sd-control-height-large);
  --sd-button-plate-radius: var(--sd-radius-full);
  --sd-button-vertical-gap: var(--sd-space-x-small);
  --sd-button-vertical-foreground: var(--sd-color-text);
  --sd-button-radius-x-small: var(--sd-radius-control-x-small);
  --sd-button-radius-small: var(--sd-radius-control-small);
  --sd-button-radius-medium: var(--sd-radius-control-medium);
  --sd-button-radius-large: var(--sd-radius-control-large);
  --sd-button-radius-x-large: var(--sd-radius-control-x-large);
  --sd-button-radius-circle: var(--sd-radius-full);
  --sd-button-height-x-small: var(--sd-control-height-x-small);
  --sd-button-height-small: var(--sd-control-height-small);
  --sd-button-height-medium: var(--sd-control-height-medium);
  --sd-button-height-large: var(--sd-control-height-large);
  --sd-button-height-x-large: var(--sd-control-height-x-large);
  --sd-button-padding-inline-x-small: var(--sd-space-x-small);
  --sd-button-padding-inline-small: var(--sd-space-x-small);
  --sd-button-padding-inline-medium: var(--sd-space-small);
  --sd-button-padding-inline-large: var(--sd-space-medium);
  --sd-button-padding-inline-x-large: var(--sd-space-medium);
  --sd-button-padding-inline-ghost-x-small: var(--sd-space-2x-small);
  --sd-button-padding-inline-ghost-small: var(--sd-space-2x-small);
  --sd-button-padding-inline-ghost-medium: var(--sd-space-x-small);
  --sd-button-padding-inline-ghost-large: var(--sd-space-small);
  --sd-button-padding-inline-ghost-x-large: var(--sd-space-small);
  --sd-button-background-primary: var(--sd-color-fill-brand);
  --sd-button-background-secondary: var(--sd-color-fill-secondary);
  --sd-button-background-outline: transparent;
  --sd-button-background-destructive: var(--sd-color-fill-destructive);
  --sd-button-background-ghost: transparent;
  --sd-button-background-surface: var(--sd-color-surface);
  --sd-button-background-tonal: var(--sd-color-fill-brand-subtle);
  --sd-button-background-strong: var(--sd-color-fill-neutral-strong);
  --sd-button-foreground-primary: var(--sd-color-text-on-color);
  --sd-button-foreground-secondary: var(--sd-color-text);
  --sd-button-foreground-outline: var(--sd-color-text);
  --sd-button-foreground-destructive: var(--sd-color-text-on-destructive);
  --sd-button-foreground-ghost: var(--sd-color-text);
  --sd-button-foreground-surface: var(--sd-color-text);
  --sd-button-foreground-tonal: var(--sd-color-text-brand);
  --sd-button-foreground-strong: var(--sd-color-text-on-neutral-strong);
  --sd-button-border-outline: var(--sd-color-border-subtle);
  --sd-button-border-secondary: var(--sd-color-border-secondary);
  --sd-button-icon-size-x-small: var(--sd-icon-small);
  --sd-button-icon-size-small: var(--sd-icon-medium);
  --sd-button-icon-size-medium: var(--sd-icon-large);
  --sd-button-icon-size-large: var(--sd-icon-x-large);
  --sd-button-icon-size-x-large: var(--sd-icon-x-large);
  --sd-button-border-width: var(--sd-border-thin);
  --sd-button-text-padding-inline: var(--sd-space-2x-small);

  /* textfield */
  --sd-textfield-label-group-gap: var(--sd-space-2x-small);
  --sd-textfield-text-padding-inline: var(--sd-text-inset-inline);
  --sd-textfield-gap: var(--sd-space-x-small);
  --sd-textfield-label-foreground: var(--sd-color-text);
  --sd-textfield-group-background: var(--sd-color-surface-inset);
  --sd-textfield-group-background-readonly: var(--sd-color-surface);
  --sd-textfield-group-background-underline: transparent;
  --sd-textfield-group-border: var(--sd-color-border);
  --sd-textfield-group-border-hover: var(--sd-color-border-hover);
  --sd-textfield-group-border-focus: var(--sd-color-border-focus);
  --sd-textfield-group-border-invalid: var(--sd-color-border-invalid);
  --sd-textfield-group-radius-x-small: var(--sd-radius-control-x-small);
  --sd-textfield-group-radius-small: var(--sd-radius-control-small);
  --sd-textfield-group-radius-medium: var(--sd-radius-control-medium);
  --sd-textfield-group-radius-large: var(--sd-radius-control-large);
  --sd-textfield-group-radius-x-large: var(--sd-radius-control-x-large);
  --sd-textfield-group-height-x-small: var(--sd-control-height-x-small);
  --sd-textfield-group-height-small: var(--sd-control-height-small);
  --sd-textfield-group-height-medium: var(--sd-control-height-medium);
  --sd-textfield-group-height-large: var(--sd-control-height-large);
  --sd-textfield-group-height-x-large: var(--sd-control-height-x-large);
  --sd-textfield-group-padding-inline-x-small: var(--sd-space-small);
  --sd-textfield-group-padding-inline-small: var(--sd-space-small);
  --sd-textfield-group-padding-inline-medium: var(--sd-space-medium);
  --sd-textfield-group-padding-inline-large: var(--sd-space-large);
  --sd-textfield-group-padding-inline-x-large: var(--sd-space-large);
  --sd-textfield-group-padding-inline-underline: var(--sd-text-inset-inline);
  --sd-textfield-group-border-width: var(--sd-border-thin);
  --sd-textfield-group-gap: var(--sd-space-x-small);
  --sd-textfield-input-foreground: var(--sd-color-text);
  --sd-textfield-input-placeholder: var(--sd-color-text-placeholder);
  --sd-textfield-description-foreground: var(--sd-color-text-muted);
  --sd-textfield-error-foreground: var(--sd-color-text-error);
  --sd-textfield-leading-foreground: var(--sd-color-text-muted);
  --sd-textfield-trailing-foreground: var(--sd-color-text-muted);

  /* button-group */
  --sd-button-group-gap: var(--sd-space-x-small);

  /* badge */
  --sd-badge-gap: var(--sd-space-2x-small);
  --sd-badge-icon-font-size: var(--sd-icon-small);
  --sd-badge-dot-size: 0.5rem;
  --sd-badge-dot-radius: var(--sd-radius-full);
  --sd-badge-dot-background: var(--sd-color-fill-live);
  --sd-badge-radius: var(--sd-radius-full);
  --sd-badge-height-small: var(--sd-size-small);
  --sd-badge-padding-inline-small: var(--sd-space-2x-small);
  --sd-badge-padding-inline-medium: var(--sd-space-x-small);
  --sd-badge-padding-block: var(--sd-space-2x-small);
  --sd-badge-background-overlay: var(--sd-color-background-inverse);
  --sd-badge-background-neutral: var(--sd-color-surface);
  --sd-badge-background-tonal: var(--sd-color-fill-brand-subtle);
  --sd-badge-background-primary: var(--sd-color-fill-brand);
  --sd-badge-background-strong: var(--sd-color-fill-neutral-strong);
  --sd-badge-background-success: var(--sd-color-fill-success-subtle);
  --sd-badge-background-warning: var(--sd-color-fill-warning-subtle);
  --sd-badge-background-info: var(--sd-color-fill-info-subtle);
  --sd-badge-background-error: var(--sd-color-fill-error-subtle);
  --sd-badge-background-urgency: var(--sd-color-fill-urgency-subtle);
  --sd-badge-background-category-1: var(--sd-color-fill-category-1);
  --sd-badge-background-category-2: var(--sd-color-fill-category-2);
  --sd-badge-background-category-3: var(--sd-color-fill-category-3);
  --sd-badge-background-category-4: var(--sd-color-fill-category-4);
  --sd-badge-background-category-5: var(--sd-color-fill-category-5);
  --sd-badge-background-category-6: var(--sd-color-fill-category-6);
  --sd-badge-background-category-7: var(--sd-color-fill-category-7);
  --sd-badge-background-category-8: var(--sd-color-fill-category-8);
  --sd-badge-foreground-overlay: var(--sd-color-text-inverse);
  --sd-badge-foreground-neutral: var(--sd-color-text);
  --sd-badge-foreground-tonal: var(--sd-color-text-brand);
  --sd-badge-foreground-primary: var(--sd-color-text-on-color);
  --sd-badge-foreground-strong: var(--sd-color-text-on-neutral-strong);
  --sd-badge-foreground-success: var(--sd-color-text-success);
  --sd-badge-foreground-warning: var(--sd-color-text-warning);
  --sd-badge-foreground-info: var(--sd-color-text-info);
  --sd-badge-foreground-error: var(--sd-color-text-error);
  --sd-badge-foreground-urgency: var(--sd-color-text-urgency);
  --sd-badge-foreground-category: var(--sd-color-text-on-color);
  --sd-badge-border-neutral: var(--sd-color-border-decorative);
  --sd-badge-border-width: var(--sd-border-thin);

  /* field-button */
  --sd-field-button-gap: var(--sd-space-2x-small);
  --sd-field-button-text-padding-inline: var(--sd-space-2x-small);
  --sd-field-button-background: var(--sd-color-surface);
  --sd-field-button-foreground: var(--sd-color-text);
  --sd-field-button-inside-label-foreground: var(--sd-color-text-muted);
  --sd-field-button-border: var(--sd-color-border);
  --sd-field-button-border-hover: var(--sd-color-border-hover);
  --sd-field-button-border-focus: var(--sd-color-border-focus);
  --sd-field-button-border-width: var(--sd-border-thin);
  --sd-field-button-radius-capsule: var(--sd-radius-full);
  --sd-field-button-radius-x-small: var(--sd-radius-control-x-small);
  --sd-field-button-radius-small: var(--sd-radius-control-small);
  --sd-field-button-radius-medium: var(--sd-radius-control-medium);
  --sd-field-button-radius-large: var(--sd-radius-control-large);
  --sd-field-button-radius-x-large: var(--sd-radius-control-x-large);
  --sd-field-button-height-x-small: var(--sd-control-height-x-small);
  --sd-field-button-height-small: var(--sd-control-height-small);
  --sd-field-button-height-medium: var(--sd-control-height-medium);
  --sd-field-button-height-large: var(--sd-control-height-large);
  --sd-field-button-height-x-large: var(--sd-control-height-x-large);
  --sd-field-button-padding-inline-x-small: var(--sd-space-x-small);
  --sd-field-button-padding-inline-small: var(--sd-space-x-small);
  --sd-field-button-padding-inline-medium: var(--sd-space-small);
  --sd-field-button-padding-inline-large: var(--sd-space-medium);
  --sd-field-button-padding-inline-x-large: var(--sd-space-medium);
  --sd-field-button-icon-foreground: var(--sd-color-icon-muted);

  /* select */
  --sd-select-inside-label-foreground: var(--sd-color-text-muted);
  --sd-select-label-group-gap: var(--sd-space-2x-small);
  --sd-select-text-padding-inline: var(--sd-text-inset-inline);
  --sd-select-gap: var(--sd-space-x-small);
  --sd-select-label-foreground: var(--sd-color-text);
  --sd-select-trigger-gap: var(--sd-space-small);
  --sd-select-trigger-background: var(--sd-color-surface-inset);
  --sd-select-trigger-background-filled: var(--sd-color-fill-neutral-subtle);
  --sd-select-trigger-foreground: var(--sd-color-text);
  --sd-select-trigger-font-size-x-small: var(--sd-type-label-medium-font-size);
  --sd-select-trigger-font-size-small: var(--sd-type-label-medium-font-size);
  --sd-select-trigger-font-size-medium: var(--sd-type-label-large-font-size);
  --sd-select-trigger-font-size-large: var(--sd-type-body-large-font-size);
  --sd-select-trigger-font-size-x-large: var(--sd-type-body-large-font-size);
  --sd-select-trigger-border: var(--sd-color-border);
  --sd-select-trigger-border-hover: var(--sd-color-border-hover);
  --sd-select-trigger-border-focus: var(--sd-color-border-focus);
  --sd-select-trigger-border-invalid: var(--sd-color-border-invalid);
  --sd-select-trigger-border-filled: transparent;
  --sd-select-trigger-radius-x-small: var(--sd-radius-control-x-small);
  --sd-select-trigger-radius-small: var(--sd-radius-control-small);
  --sd-select-trigger-radius-medium: var(--sd-radius-control-medium);
  --sd-select-trigger-radius-large: var(--sd-radius-control-large);
  --sd-select-trigger-radius-x-large: var(--sd-radius-control-x-large);
  --sd-select-trigger-height-x-small: var(--sd-control-height-x-small);
