  --sd-state-pressed-neutral-subtle: var(--sd-ref-palette-white-alpha-120);
  --sd-state-pressed-neutral: var(--sd-ref-palette-white-alpha-120);
  --sd-state-pressed-selected: var(--sd-ref-palette-white-alpha-120);
  --sd-state-pressed-secondary: var(--sd-ref-palette-alpha-150);

    /* focus-ring */
  --sd-state-focus-ring: var(--sd-ref-palette-amber-500);
  }
}

/* Inverse ground — "translucent" surface treatment, re-declared so it resolves against the swapped roles */
:root[data-surface="translucent"] [data-ground="inverse"] {
  --sd-surface-treatment-overlay-background: var(--sd-color-surface-overlay-translucent);
}

/* reset.css — 최소 초기화 (룩은 tokens.css/컴포넌트가 담당) */
*,
*::before,
*::after {
  box-sizing: border-box;
}

* {
  margin: 0;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  min-height: 100vh;
  font-family: var(--sd-font-family);
  color: var(--sd-color-text);
  background: var(--sd-color-background);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* An inverse ground (`data-ground="inverse"`, set by Band tone="inverse") swaps every colour role in its
   subtree to the opposite theme. The ink above was resolved at <body> and inherits as a finished colour,
   so the ground re-inks itself the same way the body does. */
[data-ground="inverse"] {
  color: var(--sd-color-text);
}

/* Korean wraps between words, not between syllables. `keep-all` changes CJK only, and it is
   scoped to `:lang(ko)` because Japanese and Chinese set no spaces: under `keep-all` a line of
   either would not break at all. So a Korean page declares its language (`<html lang="ko">`, or
   `lang` on the element) and gets it; nothing else moves. `overflow-wrap` keeps one long run
   without a space (a URL, a compound) from overflowing its box. */
:lang(ko) {
  word-break: keep-all;
  overflow-wrap: break-word;
}

button,
input,
select,
textarea {
  font: inherit;
  color: inherit;
}

/* Text selection — the `selection` Sys color role's intended consumer
   (naming-convention § Semantic color: selection = `::selection` colors). */
::selection {
  background: var(--sd-color-selection-background);
  color: var(--sd-color-selection-foreground);
}

/* Screen-reader-only content — visually hidden but still announced/focusable.
   Utility class, not a component: nothing here has a "look" to own. */
.sd-visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

/* Tabular figures — line digits up in columns (tables, data cells, aligned numbers).
   Opt-in utility, not a type role: tabular-nums is on/off (no scale to derive), applied where
   numbers must align. Pair with any `.sd-type-*` role. */
.sd-tabular {
  font-variant-numeric: tabular-nums;
}
